#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int minMaxWaitingTime(std::vector<int>& times, int m) {
        int low = *std::max_element(times.begin(), times.end());
        int high = std::accumulate(times.begin(), times.end(), 0);

        auto canDistribute = [&](int limit) {
            int used = 1, cur = 0;
            for (int t : times) {
                if (cur + t > limit) {
                    used++;
                    cur = t;
                    if (used > m) return false;
                } else {
                    cur += t;
                }
            }
            return true;
        };

        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canDistribute(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minMaxWaitingTime(int[] times, int m) {
        int low = 0, high = 0;
        for (int t : times) {
            low = Math.max(low, t);
            high += t;
        }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int used = 1, cur = 0;
            boolean ok = true;
            for (int t : times) {
                if (cur + t > mid) {
                    used++;
                    cur = t;
                    if (used > m) { ok = false; break; }
                } else {
                    cur += t;
                }
            }
            if (ok) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

function minMaxWaitingTime(times, m) {
    let low = Math.max(...times);
    let high = times.reduce((a, b) => a + b, 0);
    let ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let used = 1, cur = 0, ok = true;
        for (const t of times) {
            if (cur + t > mid) {
                used++;
                cur = t;
                if (used > m) { ok = false; break; }
            } else {
                cur += t;
            }
        }
        if (ok) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}
